/**
 * W1 decide knobs (R17). These live in pipeline-config.json under
 * `thresholds.decide` but are not yet part of the typed PipelineThresholds
 * `decide?` block (the impact-aware flags own that surface), so we read them
 * defensively here. The built-in defaults match the documented config so the
 * behaviour is identical whether or not the config file carries the block.
 */
interface DecideEdgeKnobs {
  uniformFlagSpread: number;
  uniformFlagMaxDelta: number;
  enforceNonGoNoTargetState: boolean;
  recomputeComplianceAllClasses: boolean;
}

function decideEdgeKnobs(thresholds?: PipelineThresholds): DecideEdgeKnobs {
  const raw = (thresholds?.decide ?? {}) as UnknownRecord;
  const num = (v: unknown, fallback: number): number =>
    typeof v === 'number' && Number.isFinite(v) ? v : fallback;
  const bool = (v: unknown, fallback: boolean): boolean =>
    typeof v === 'boolean' ? v : fallback;
  return {
    uniformFlagSpread:             num(raw['uniformFlagSpread'], 0.05),
    uniformFlagMaxDelta:           num(raw['uniformFlagMaxDelta'], 0.05),
    enforceNonGoNoTargetState:     bool(raw['enforceNonGoNoTargetState'], true),
    recomputeComplianceAllClasses: bool(raw['recomputeComplianceAllClasses'], true),
  };
}

